// Unifica la imagen (Webhook o Form), produce data URL base64 para OpenRouter
// y precalcula la ruta + URL PUBLICA del bucket de Supabase.
// Usa getBinaryDataBuffer para que funcione tambien en binaryDataMode=database.
const SUPABASE_URL = 'https://supabase.sistemaindumentaria.com';
const BUCKET = 'comprobantes';
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  if (keys.length === 0) { throw new Error('No se recibio ninguna imagen (binary vacio).'); }
  const key = bin.foto ? 'foto' : keys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const base64 = buffer.toString('base64');
  const mimeType = bin[key].mimeType || 'image/jpeg';
  const meta = item.json || {};
  const ext = (mimeType.indexOf('png') >= 0) ? 'png' : ((mimeType.indexOf('webp') >= 0) ? 'webp' : 'jpg');
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = ('0' + (now.getMonth() + 1)).slice(-2);
  const rand = Math.floor(Math.random() * 1000000);
  const storagePath = yyyy + '/' + mm + '/nota_' + now.getTime() + '_' + rand + '.' + ext;
  const comprobanteUrl = SUPABASE_URL + '/storage/v1/object/public/' + BUCKET + '/' + storagePath;

  // Extract body values if webhook
  const body = meta.body || {};
  const clientRequestId = meta.client_request_id || meta['client_request_id (opcional)'] || body.client_request_id || null;
  const tipoHint = meta.tipo || meta['Tipo (opcional)'] || body.tipo || body.tipo_hint || null;

  out.push({
    json: {
      mimeType: mimeType,
      dataUrl: 'data:' + mimeType + ';base64,' + base64,
      storage_path: storagePath,
      comprobante_url: comprobanteUrl,
      client_request_id: clientRequestId,
      tipo_hint: tipoHint
    },
    binary: { foto: bin[key] }
  });
}
return out;

const meta = $('Normalizar imagen2').first().json;
const prompt = `Eres un extractor de datos de 'ORDENES DE MOVIMIENTO DE MERCANCIA' escritas a mano. Analiza la imagen y devuelve UNICAMENTE un JSON valido con esta forma exacta:
{
  "folio": string|null,
  "fecha": string|null,
  "tipo_movimiento": null,
  "origen": string|null,
  "destino": string|null,
  "lineas": [
    { "cantidad_cajas": number|null, "piezas_por_caja": number|null, "estilo_raw": string|null, "descripcion_raw": string|null, "confianza": number }
  ],
  "confianza_global": number
}
Reglas:
- Incluye solo renglones CON contenido. No inventes lineas vacias.
- CANTIDAD suele venir como 'N X M' (N cajas de M piezas). Si solo hay un numero, ponlo en cantidad_cajas y piezas_por_caja=null.
- La columna DESCRIPCION es el codigo/SKU (letras+numeros). Copialo EXACTO, respetando mayusculas. Cada renglon tiene su PROPIA descripcion; NO repitas el mismo SKU salvo que este escrito identico.
- Si el encabezado trae 'A / B', A=origen y B=destino.
- tipo_movimiento: devuelve SIEMPRE null (el sistema lo deduce de origen/destino).
- FECHA en formato YYYY-MM-DD (interpreta DD-MM-YY del encabezado). Si no es legible, usa null.
- Devuelve SOLO el JSON, sin markdown ni texto adicional.`;
const body = {
  model: 'google/gemma-4-26b-a4b-it:free',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'user', content: [
      { type: 'text', text: prompt },
      { type: 'image_url', image_url: { url: meta.dataUrl } }
    ] }
  ]
};
return [{ json: { body: body, client_request_id: meta.client_request_id, comprobante_url: meta.comprobante_url, tipo_hint: meta.tipo_hint } }];

const resp = $json;
let text = '';
try { text = resp.choices[0].message.content; }
catch (e) { throw new Error('Respuesta inesperada de OpenRouter: ' + JSON.stringify(resp).slice(0, 600)); }
text = String(text).replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let data;
try { data = JSON.parse(text); }
catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) { throw new Error('El modelo no devolvio JSON valido: ' + text.slice(0, 300)); }
  data = JSON.parse(m[0]);
}
const meta = $('Construir prompt + body2').first().json;
if ((!data.tipo_movimiento) && meta.tipo_hint) { data.tipo_movimiento = meta.tipo_hint; }
const payload = {
  client_request_id: meta.client_request_id || null,
  comprobante_url: meta.comprobante_url || null,
  folio: data.folio || null,
  fecha: data.fecha || null,
  tipo_movimiento: data.tipo_movimiento || null,
  origen: data.origen || null,
  destino: data.destino || null,
  lineas: data.lineas || [],
  confianza_global: data.confianza_global || null,
  json_crudo: data
};
return [{ json: Object.assign({}, payload, { payload_json: JSON.stringify(payload), lineas_json: JSON.stringify(data.lineas || []) }) }];

