let prom = {};
try { prom = $('Promover a nota (auto)').first().json; } catch (e) { prom = {}; }
const res = prom.resultado || prom || {};
let propuestaId = null;
try { propuestaId = $('Insertar propuesta staging').first().json.id; } catch(e) {}
