const cands = $input.all().map(x => x.json);
const ocr = $('Parsear JSON').first().json;
const prep = $('Preparar').first().json;
const OLLAMA_URL = 'http://ollama:11434';
const MODEL = 'gemma3:latest';
const TH = 0.45;
const GAP = 0.07;
const self = this;
function top(campo) {
  return cands.filter(r => r.campo === campo).sort((a, b) => b.score - a.score || a.id - b.id);
}
async function resolver(campo, texto) {
  const c = top(campo);
  if (!c.length || !texto) return null;
  if (c[0].score >= TH && (!c[1] || (c[0].score - c[1].score) >= GAP)) return c[0].id;
  const lista = c.slice(0, 5).map(x => x.codigo + ' - ' + x.nombre).join('; ');
  const prompt = 'Detecte la bodega "' + texto + '". Opciones validas (codigo - nombre): ' + lista + '. Devuelve SOLO {"codigo":"<exacto de la lista>"} de la mas probable, o {"codigo":null} si ninguna encaja.';
  try {
    const resp = await self.helpers.httpRequest({ method: 'POST', url: OLLAMA_URL + '/api/generate', body: { model: MODEL, prompt: prompt, stream: false, format: 'json', options: { temperature: 0 } }, json: true });
    const pick = JSON.parse(resp.response);
    if (pick && pick.codigo) { const hit = c.find(x => x.codigo === pick.codigo); if (hit) return hit.id; }
  } catch (e) {}
  return c[0].id;
}
const bodega_origen_id = await resolver('origen', ocr.origen);
const bodega_destino_id = await resolver('destino', ocr.destino);
